        (14, r"\lim_{x \to 2} \frac{\sqrt{2x+5}-3}{x-2}\text{의 값은?}", "\\frac{1}{3}", ["0", "\\frac{1}{6}", "\\frac{1}{2}", "1"], r"$$\frac{2}{\sqrt{2x+5}+3} \to \frac{2}{6} = \frac{1}{3}$$", ""),
        (15, r"\lim_{x \to 1} \frac{\sqrt{3x+1}-2}{x-1}\text{의 값은?}", "\\frac{3}{4}", ["\\frac{1}{4}", "\\frac{1}{2}", "1", "\\frac{3}{2}"], r"$$\frac{3}{\sqrt{3x+1}+2} \to \frac{3}{4}$$", ""),
        (16, r"\lim_{x \to 0} \frac{\sqrt{4+x}-\sqrt{4-x}}{x}\text{의 값은?}", "\\frac{1}{2}", ["0", "\\frac{1}{4}", "1", "2"], r"$$\frac{2x}{x(\sqrt{4+x}+\sqrt{4-x})} \to \frac{2}{4} = \frac{1}{2}$$", ""),
