        (3, r"\lim_{x \to 0^+} \frac{|x|}{x}\text{의 값은?}", "1", ["-2", "-1", "0", "2"], r"$x>0$이므로 $\frac{x}{x} = 1$", ""),
        (4, r"\lim_{x \to 0^-} \frac{|x|}{x}\text{의 값은?}", "-1", ["-2", "0", "1", "2"], r"$x<0$이므로 $\frac{-x}{x} = -1$", ""),
        (5, r"\lim_{x \to 1^+} [x]\text{의 값은? (단, } [x]\text{는 가우스 기호)}", "1", ["-1", "0", "2", "3"], r"$x \to 1^+$일 때 $[x] = 1$", ""),
        (6, r"\lim_{x \to 1^-} [x]\text{의 값은?}", "0", ["-2", "-1", "1", "2"], r"$x \to 1^-$일 때 $[x] = 0$", ""),
        (7, r"\text{그래프에서 } \lim_{x \to 1^-} f(x) + \lim_{x \to 2^+} f(x)\text{의 값은?}", "3", ["1", "2", "4", "5"], r"2014학년도 모의평가: $1 + 2 = 3$", "2014학년도 모의평가"),
        (8, r"\text{그래프에서 } \lim_{x \to 0^-} f(x) + \lim_{x \to 1^+} f(x)\text{의 값은?}", "2", ["0", "1", "3", "4"], r"2015학년도 수능: $1 + 1 = 2$", "2015학년도 수능"),
        (9, r"\text{그래프에서 } \lim_{x \to -1^+} f(x) + \lim_{x \to 1^-} f(x)\text{의 값은?}", "3", ["1", "2", "4", "5"], r"2016학년도 수능: $2 + 1 = 3$", "2016학년도 수능"),
        (10, r"\text{그래프에서 } \lim_{x \to 0^+} f(x) + \lim_{x \to 2^-} f(x)\text{의 값은?}", "4", ["1", "2", "3", "5"], r"2017학년도 모의평가: $2 + 2 = 4$", "2017학년도 모의평가"),
        (11, r"\text{그래프에서 } \lim_{x \to 1^+} f(x) - \lim_{x \to 1^-} f(x)\text{의 값은?}", "2", ["-1", "0", "1", "3"], r"2017학년도 수능: $3 - 1 = 2$", "2017학년도 수능"),
        (12, r"\text{그래프에서 } \lim_{x \to -1^-} f(x) + \lim_{x \to 1^+} f(x)\text{의 값은?}", "3", ["0", "1", "2", "4"], r"2018학년도 모의평가: $1 + 2 = 3$", "2018학년도 모의평가"),
        (13, r"\text{그래프에서 } \lim_{x \to 0^-} f(x) + \lim_{x \to 2^+} f(x)\text{의 값은?}", "1", ["-1", "0", "2", "3"], r"2018학년도 수능: $0 + 1 = 1$", "2018학년도 수능"),
        (14, r"\lim_{x \to 2^+} \frac{|x-2|}{x-2}\text{의 값은?}", "1", ["-2", "-1", "0", "2"], r"$x>2$이므로 $\frac{x-2}{x-2} = 1$", ""),
        (15, r"\lim_{x \to 2^-} \frac{|x-2|}{x-2}\text{의 값은?}", "-1", ["-2", "0", "1", "2"], r"$x<2$이므로 $\frac{-(x-2)}{x-2} = -1$", ""),
        (16, r"f(x) = \begin{cases} 2x+1 & (x \ge 1) \\ x^2-1 & (x < 1) \end{cases}\text{일 때, } \lim_{x \to 1^+} f(x)\text{의 값은?}", "3", ["0", "1", "2", "4"], r"$$2(1)+1 = 3$$", ""),
        (17, r"f(x) = \begin{cases} 2x+1 & (x \ge 1) \\ x^2-1 & (x < 1) \end{cases}\text{일 때, } \lim_{x \to 1^-} f(x)\text{의 값은?}", "0", ["-1", "1", "2", "3"], r"$$1^2-1 = 0$$", ""),
        (18, r"\text{그래프에서 } \lim_{x \to 0^+} f(x) \times \lim_{x \to 1^-} f(x)\text{의 값은?}", "4", ["1", "2", "3", "5"], r"$$2 \times 2 = 4$$", ""),
        (19, r"\text{그래프에서 } \lim_{x \to -2^+} f(x) + \lim_{x \to 2^-} f(x)\text{의 값은?}", "1", ["-1", "0", "2", "3"], r"$$0 + 1 = 1$$", ""),
        (20, r"\text{그래프에서 } \lim_{x \to 1^+} f(x) + f(1)\text{의 값은?}", "3", ["1", "2", "4", "5"], r"$$2 + 1 = 3$$", ""),
        (21, r"\text{그래프에서 } \lim_{x \to 0} f(x)\text{가 존재할 때, 그 극한값은?}", "2", ["-1", "0", "1", "3"], r"좌극한=우극한=$2$이므로 극한값은 $2$입니다.", ""),
        (22, r"\lim_{x \to 3^+} \frac{x-3}{|x-3|}\text{의 값은?}", "1", ["-1", "0", "2", "3"], r"극한값은 $1$입니다.", ""),
        (23, r"\lim_{x \to 3^-} \frac{x-3}{|x-3|}\text{의 값은?}", "-1", ["-2", "0", "1", "2"], r"극한값은 $-1$입니다.", ""),
