        (4, r"f(x) = \begin{cases} \frac{x^2-4}{x-2} & (x \ne 2) \\ a & (x = 2) \end{cases}\text{이 } x=2\text{에서 연속일 때, } a\text{의 값은?}", "4", ["1", "2", "3", "5"], r"$$a = \lim_{x \to 2} (x+2) = 4$$", ""),
        (5, r"f(x) = \begin{cases} x^2+ax & (x \ge 1) \\ 3x-1 & (x < 1) \end{cases}\text{이 } x=1\text{에서 연속일 때, } a\text{의 값은?}", "1", ["-1", "0", "2", "3"], r"$1+a = 3(1)-1 \implies 1+a=2 \implies a=1$", ""),
        (6, r"f(x) = \begin{cases} ax+2 & (x \ge 2) \\ x^2-a & (x < 2) \end{cases}\text{이 } x=2\text{에서 연속일 때, } a\text{의 값은?}", "\\frac{2}{3}", ["\\frac{1}{3}", "1", "\\frac{4}{3}", "2"], r"$2a+2 = 4-a \implies 3a=2 \implies a=\frac{2}{3}$", ""),
        (7, r"f(x) = \begin{cases} 2x+a & (x \ge 2) \\ x^2-1 & (x < 2) \end{cases}\text{이 } x=2\text{에서 연속일 때, } a\text{의 값은?}", "-1", ["-3", "-2", "0", "1"], r"2014학년도 모의평가: $4+a = 3 \implies a=-1$", "2014학년도 모의평가"),
        (8, r"f(x) = \begin{cases} 3x+a & (x \ge 1) \\ 2x^2+1 & (x < 1) \end{cases}\text{이 } x=1\text{에서 연속일 때, } a\text{의 값은?}", "0", ["-2", "-1", "1", "2"], r"2015학년도 수능: $3+a = 3 \implies a=0$", "2015학년도 수능"),
        (9, r"f(x) = \begin{cases} x^2+a & (x \ge 2) \\ 5x-2 & (x < 2) \end{cases}\text{이 } x=2\text{에서 연속일 때, } a\text{의 값은?}", "4", ["1", "2", "3", "5"], r"2016학년도 모의평가: $4+a = 8 \implies a=4$", "2016학년도 모의평가"),
        (10, r"f(x) = \begin{cases} ax+3 & (x \ge 1) \\ 2x+1 & (x < 1) \end{cases}\text{이 } x=1\text{에서 연속일 때, } a\text{의 값은?}", "0", ["-2", "-1", "1", "2"], r"2016학년도 수능: $a+3 = 3 \implies a=0$", "2016학년도 수능"),
        (11, r"f(x) = \begin{cases} \frac{x^2+ax-6}{x-2} & (x \ne 2) \\ b & (x = 2) \end{cases}\text{이 실수 전체에서 연속일 때, } a+b\text{의 값을 구하시오.}", "6", [], r"2017학년도 모의평가: $4+2a-6=0 \implies a=1$. $b = \lim (x+3) = 5$. $a+b=6$", "2017학년도 모의평가"),
        (12, r"f(x) = \begin{cases} 2x+a & (x \ge 3) \\ x^2-3 & (x < 3) \end{cases}\text{이 } x=3\text{에서 연속일 때, } a\text{의 값은?}", "0", ["-2", "-1", "1", "2"], r"2017학년도 수능: $6+a = 6 \implies a=0$", "2017학년도 수능"),
        (13, r"f(x) = \begin{cases} ax+1 & (x \ge 2) \\ x^2-3x+5 & (x < 2) \end{cases}\text{이 } x=2\text{에서 연속일 때, } a\text{의 값은?}", "1", ["-1", "0", "2", "3"], r"2018학년도 모의평가: $2a+1 = 3 \implies a=1$", "2018학년도 모의평가"),
        (14, r"f(x) = \begin{cases} 3x+a & (x \ge 2) \\ x^2+2 & (x < 2) \end{cases}\text{이 } x=2\text{에서 연속일 때, } a\text{의 값은?}", "0", ["-2", "-1", "1", "2"], r"2018학년도 수능: $6+a = 6 \implies a=0$", "2018학년도 수능"),
        (15, r"f(x) = \begin{cases} \frac{x^2-16}{x-4} & (x \ne 4) \\ a & (x = 4) \end{cases}\text{이 } x=4\text{에서 연속일 때, } a\text{의 값을 구하시오.}", "8", [], r"$$a = \lim_{x \to 4} (x+4) = 8$$", ""),
        (16, r"f(x) = \begin{cases} ax+b & (x \ge 1) \\ 2x^2+1 & (x < 1) \end{cases}\text{이 연속이고 } f(2)=7\text{일 때, } a\text{의 값은?}", "4", ["1", "2", "3", "5"], r"$a+b = 3$, $2a+b=7 \implies a=4, b=-1$", ""),
