        (20, r"f(x) = \begin{cases} \frac{x^2+x-2}{x-1} & (x \ne 1) \\ a & (x = 1) \end{cases}\text{이 } x=1\text{에서 연속일 때, } a\text{의 값은?}", "3", ["0", "1", "2", "4"], r"$$a = \lim_{x \to 1} (x+2) = 3$$", ""),
        (21, r"f(x) = \begin{cases} 2x+a & (x \ge 3) \\ x^2-2x & (x < 3) \end{cases}\text{이 } x=3\text{에서 연속일 때, } a\text{의 값은?}", "-3", ["-5", "-4", "-2", "-1"], r"$6+a = 3 \implies a=-3$", ""),
        (22, r"f(x) = \begin{cases} ax-3 & (x \ge 2) \\ x+1 & (x < 2) \end{cases}\text{이 } x=2\text{에서 연속일 때, } a\text{의 값은?}", "3", ["1", "2", "4", "5"], r"$2a-3 = 3 \implies 2a=6 \implies a=3$", ""),
