        (24, r"f(x) = \begin{cases} \frac{x^2-25}{x-5} & (x \ne 5) \\ a & (x = 5) \end{cases}\text{이 연속일 때, } a\text{의 값을 구하시오.}", "10", [], r"$$a = \lim_{x \to 5} (x+5) = 10$$", ""),
        (25, r"f(x) = \begin{cases} 3x+a & (x \ge 0) \\ x^2-2 & (x < 0) \end{cases}\text{이 } x=0\text{에서 연속일 때, } a\text{의 값은?}", "-2", ["-4", "-3", "-1", "0"], r"$$a = -2$$", ""),
        (26, r"f(x) = \begin{cases} ax+1 & (x \ge 3) \\ x^2-5 & (x < 3) \end{cases}\text{이 } x=3\text{에서 연속일 때, } a\text{의 값을 구하시오.}", "1", [], r"$$3a+1 = 4 \implies a=1$$", ""),
